package com.mikasrevs.newphone.client.zphone.gui;

import com.mikasrevs.newphone.client.gui.PhoneClockState;
import com.mikasrevs.newphone.client.settings.PhoneSettingsStore;
import com.mikasrevs.newphone.client.zphone.PhoneNavigationState;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.Component;
import org.lwjgl.glfw.GLFW;

public final class ZPhoneClockScreen extends AbstractZPhoneScreen {
    public ZPhoneClockScreen(){super(Component.translatable("screen.newphone.app.clock"));}
    @Override public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g);g.fill(x(8),y(8),x(292),y(602),0xFF07090D);drawStatusBar(g);drawText(g,PhoneSettingsStore.text("Saat","Clock"),22,58,20,0xFFFFFFFF,false);String local=com.mikasrevs.newphone.client.gui.PhoneTimeDisplay.time(true);drawText(g,local,150,104,28,0xFFFFFFFF,true);drawText(g,com.mikasrevs.newphone.client.gui.PhoneTimeDisplay.dayLabel()+" / "+minecraftClock(),150,149,9,0xFF8D99A8,true);
        drawRoundedRect(g,x(20),y(187),x(280),y(276),size(15),0xFF151B24);drawText(g,PhoneSettingsStore.text("DÜNYA SAATİ","WORLD CLOCK"),33,201,7,0xFF818D9B,false);world(g,"Istanbul",ZoneId.of("Europe/Istanbul"),223);world(g,"London",ZoneId.of("Europe/London"),248);
        drawRoundedRect(g,x(20),y(293),x(280),y(414),size(15),0xFF151B24);drawText(g,PhoneSettingsStore.text("KRONOMETRE","STOPWATCH"),33,307,7,0xFF818D9B,false);drawText(g,duration(PhoneClockState.stopwatchElapsedMs(),true),150,334,21,0xFFFFFFFF,true);button(g,35,377,142,402,PhoneSettingsStore.text(PhoneClockState.stopwatchRunning()?"Duraklat":"Başlat",PhoneClockState.stopwatchRunning()?"Pause":"Start",PhoneClockState.stopwatchRunning()?"Pausar":"Iniciar"),0xFF32D06C);button(g,158,377,265,402,PhoneSettingsStore.text("Sıfırla","Reset"),0xFF343B46);
        drawRoundedRect(g,x(20),y(430),x(280),y(554),size(15),0xFF151B24);drawText(g,PhoneSettingsStore.text("ZAMANLAYICI","TIMER"),33,444,7,0xFF818D9B,false);String timer=PhoneClockState.timerFinished()?PhoneSettingsStore.text("Süre Doldu","Time's Up"):duration(PhoneClockState.timerRemainingMs(),false);drawText(g,timer,150,467,20,PhoneClockState.timerFinished()?0xFFFF9F43:0xFFFFFFFF,true);button(g,30,514,95,541,PhoneSettingsStore.text("1 dk", "1 min"),0xFF273342);button(g,118,514,183,541,PhoneSettingsStore.text("5 dk", "5 min"),0xFF273342);button(g,206,514,271,541,(PhoneClockState.timerActive()||PhoneClockState.timerFinished())?PhoneSettingsStore.text("İptal","Cancel"):PhoneSettingsStore.text("10 dk", "10 min"),0xFF273342);drawHomeIndicator(g);drawFrame(g);}
    private void world(GuiGraphics g,String city,ZoneId zone,int top){drawText(g,city,34,top,9,0xFFFFFFFF,false);drawText(g,LocalDateTime.now(zone).format(DateTimeFormatter.ofPattern("HH:mm")),250,top,10,0xFF8CB7FF,true);}private void button(GuiGraphics g,int l,int t,int r,int b,String label,int color){drawRoundedRect(g,x(l),y(t),x(r),y(b),size(10),color);drawText(g,label,(l+r)/2.0F,t+8,8,0xFFFFFFFF,true);}
    @Override public boolean mouseClicked(double mx,double my,int b){if(b==0){if(inside(mx,my,35,377,142,402)){PhoneClockState.toggleStopwatch();return true;}if(inside(mx,my,158,377,265,402)){PhoneClockState.resetStopwatch();return true;}if(inside(mx,my,30,514,95,541)){PhoneClockState.startTimerMinutes(1);return true;}if(inside(mx,my,118,514,183,541)){PhoneClockState.startTimerMinutes(5);return true;}if(inside(mx,my,206,514,271,541)){if(PhoneClockState.timerActive()||PhoneClockState.timerFinished())PhoneClockState.cancelTimer();else PhoneClockState.startTimerMinutes(10);return true;}}return super.mouseClicked(mx,my,b);}
    @Override public boolean keyPressed(int k,int s,int m){if(k==GLFW.GLFW_KEY_SPACE){PhoneClockState.toggleStopwatch();return true;}if(k==GLFW.GLFW_KEY_R){PhoneClockState.resetStopwatch();return true;}if(k==GLFW.GLFW_KEY_ESCAPE){PhoneNavigationState.backOrHome(minecraft);return true;}return super.keyPressed(k,s,m);}private String minecraftClock(){long t=minecraft==null||minecraft.level==null?0L:Math.floorMod(minecraft.level.getDayTime(),24000L);long h=Math.floorMod(t/1000L+6L,24L),m=(t%1000L)*60L/1000L;return String.format(java.util.Locale.ROOT,"%02d:%02d",h,m);}private static String duration(long ms,boolean cs){long total=Math.max(0,ms),h=total/3600000,m=total/60000%60,s=total/1000%60;if(cs)return String.format(java.util.Locale.ROOT,"%02d:%02d:%02d.%02d",h,m,s,total/10%100);return String.format(java.util.Locale.ROOT,"%02d:%02d:%02d",h,m,s);}
}
